21	// V2: Records pageview and click analytics events from public mini-sites. Events feed into hourly/daily aggregate jobs.
22	class AnalyticsController extends ApiController
23	{
24	    use DetectsClientInfo;
25	    use HashesClientData;
26	    use ResolvesSiteFromRequest;
27	
28	    public function __construct(
29	        private AnalyticsCacheService $analyticsCache
30	    ) {}
31	
32	    public function pageview(PageviewRequest $request): JsonResponse
33	    {
34	        $data = $request->validated();
35	
36	        // Resolve site by ID or subdomain
37	        $site = $this->resolveSiteFromData($data);
38	
39	        if (! $site) {
40	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
41	            // 404 when only a subdomain was given and simply wasn't found.
42	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
43	
44	            return $this->error('Site not found', $statusCode);
45	        }
46	
47	        // Check if site is published
48	        if (! $site->is_published) {
49	            return $this->error('Site not published', 403);
50	        }
51	
52	        // Create pageview record
53	        $visit = new SiteVisit([
54	            'occurred_at' => now(),
55	            'session_id' => $data['session_id'] ?? null,
56	            'visitor_id' => $data['visitor_id'] ?? null,
57	            'ip_hash' => $this->hashIp($request->ip()),
58	            'user_agent' => $request->userAgent(),
59	            'referrer' => $data['referrer'] ?? $request->headers->get('referer'),
60	            'utm_source' => $data['utm_source'] ?? null,
61	            'utm_medium' => $data['utm_medium'] ?? null,
62	            'utm_campaign' => $data['utm_campaign'] ?? null,
63	            'country_code' => $this->detectCountryCode($request),
64	            'device_type' => $this->detectDeviceType($request->userAgent()),
65	        ]);
66	        $visit->professional_id = $site->professional_id;
67	        $visit->site_id = $site->id;
68	        $visit->save();
69	
70	        RebuildSiteHourlyAggregatesJob::dispatch(
71	            (string) $site->professional_id,
72	            $visit->occurred_at?->copy()->utc()->startOfHour()->toIso8601String() ?? now()->utc()->startOfHour()->toIso8601String()
73	        );
74	
75	        try {
76	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
77	        } catch (Throwable) {
78	        }
79	
80	        return $this->success([
81	            'message' => 'Pageview recorded',
82	            'visit_id' => $visit->id,
83	        ], 201);
84	    }
85	
86	    public function click(ClickRequest $request): JsonResponse
87	    {
88	        $data = $request->validated();
89	
90	        // Resolve site by ID or subdomain
91	        $site = $this->resolveSiteFromData($data);
92	
93	        if (! $site) {
94	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
95	            // 404 when only a subdomain was given and simply wasn't found.
96	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
97	
98	            return $this->error('Site not found', $statusCode);
99	        }
100	
101	        // Check if site is published
102	        if (! $site->is_published) {
103	            return $this->error('Site not published', 403);
104	        }
105	
106	        // Verify block exists and belongs to this site
107	        $block = Block::where('id', $data['block_id'])
108	            ->where('site_id', $site->id)
109	            ->first();
110	
111	        if (! $block) {
112	            return $this->error('Block not found or does not belong to this site', 404);
113	        }
114	
115	        $blockGroup = strtolower((string) $block->block_group);
116	        $blockType = strtolower((string) $block->block_type);
117	        $trackableSectionTypes = collect(config('sidest.section_block_types', [
118	            'gallery',
119	            'services',
120	            'shop',
121	            'booking',
122	        ]))
123	            ->filter(fn ($type) => is_string($type) && trim($type) !== '')
124	            ->map(fn (string $type) => strtolower(trim($type)))
125	            ->values()
126	            ->all();
127	        $isTrackableLink = $blockGroup === 'links' && $blockType === 'link';
128	        $isTrackableSection =
129	            $blockGroup === 'sections'
130	            && in_array($blockType, $trackableSectionTypes, true);
131	
132	        if (! $isTrackableLink && ! $isTrackableSection) {
133	            return $this->error('Block is not trackable for analytics', 422);
134	        }
135	
136	        // Check if block is active
137	        if (! $block->is_active) {
138	            return $this->error('Block is not active', 403);
139	        }
140	
141	        $click = LinkClick::runForBlockForeignKey(
142	            function (string $blockColumn) use ($request, $data, $site, $block) {
143	                $click = new LinkClick([
144	                    'occurred_at' => now(),
145	                    'session_id' => $data['session_id'] ?? null,
146	                    'visitor_id' => $data['visitor_id'] ?? null,
147	                    'ip_hash' => $this->hashIp($request->ip()),
148	                    'user_agent' => $request->userAgent(),
149	                    'referrer' => $data['referrer'] ?? $request->headers->get('referer'),
150	                    'utm_source' => $data['utm_source'] ?? null,
151	                    'utm_medium' => $data['utm_medium'] ?? null,
152	                    'utm_campaign' => $data['utm_campaign'] ?? null,
153	                ]);
154	                $click->professional_id = $site->professional_id;
155	                $click->site_id = $site->id;
156	                $click->setAttribute($blockColumn, $block->id);
157	                $click->save();
158	
159	                return $click;
160	            }
161	        );
162	
163	        if (! $click instanceof LinkClick) {
164	            return $this->error('Unable to record click due to schema mismatch', 500);
165	        }
166	
167	        RebuildSiteHourlyAggregatesJob::dispatch(
168	            (string) $site->professional_id,
169	            $click->occurred_at?->copy()->utc()->startOfHour()->toIso8601String() ?? now()->utc()->startOfHour()->toIso8601String()
170	        );
171	
172	        try {
173	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
174	        } catch (Throwable) {
175	        }
176	
177	        return $this->success([
178	            'message' => $isTrackableSection ? 'Section interaction recorded' : 'Click recorded',
179	            'click_id' => $click->id,
180	        ], 201);
181	    }
