193	        }
194	
195	        if (! $site->is_published) {
196	            return $this->error('Site not published', 403);
197	        }
198	
199	        $event = new CartEvent([
200	            'event_type' => $data['event_type'],
201	            'occurred_at' => now(),
202	            'session_id' => $data['session_id'] ?? null,
203	            'visitor_id' => $data['visitor_id'] ?? null,
204	            'ip_hash' => $this->hashIp($request->ip()),
205	            'shopify_product_id' => $data['shopify_product_id'] ?? null,
206	            'quantity' => $data['quantity'] ?? null,
207	        ]);
208	        $event->professional_id = $site->professional_id;
